def solve_model(A, marker, connect_bg=4, object_conn=4, edge_objects=True, eight_boundary=True, mark_edges=True, include_marker=False):
 R,C=len(A),len(A[0]);
 # identify 1 comps
 seen=set(); edge1=set()
 for r in range(R):
  for c in range(C):
   if A[r][c]!=1 or (r,c) in seen: continue
   q=deque([(r,c)]); seen.add((r,c)); comp1=[]
   while q:
    x,y=q.popleft(); comp1.append((x,y))
    for dr,dc in ([(1,0),(-1,0),(0,1),(0,-1)] if object_conn==4 else [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]):
     xx,yy=x+dr,y+dc
     if 0<=xx<R and 0<=yy<C and A[xx][yy]==1 and (xx,yy) not in seen: seen.add((xx,yy));q.append((xx,yy))
   if not edge_objects or any(x in (0,R-1) or y in (0,C-1) for x,y in comp1): edge1.update(comp1)
 # bg comp from marker
 mr,mc=marker; comp=set(); q=deque()
 for dr,dc in ([(1,0),(-1,0),(0,1),(0,-1)] if connect_bg==4 else [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]):
  rr,cc=mr+dr,mc+dc
  if 0<=rr<R and 0<=cc<C and A[rr][cc]==8 and (rr,cc) not in comp: comp.add((rr,cc));q.append((rr,cc))
 while q:
  r,c=q.popleft()
  for dr,dc in ([(1,0),(-1,0),(0,1),(0,-1)] if connect_bg==4 else [(dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if dr or dc]):
   rr,cc=r+dr,c+dc
   if 0<=rr<R and 0<=cc<C and A[rr][cc]==8 and (rr,cc) not in comp:comp.add((rr,cc));q.append((rr,cc))
 B=[row[:] for row in A]
 for r,c in comp:
  flag=mark_edges and (r==0 or r==R-1 or c==0 or c==C-1)
  for dr in (-1,0,1):
   for dc in (-1,0,1):
    if not (dr or dc):continue
    rr,cc=r+dr,c+dc
    if not (0<=rr<R and 0<=cc<C):flag=True
    elif (rr,cc) in edge1 or (include_marker and A[rr][cc]==6):flag=True
  if flag:B[r][c]=7
 return B
